<?php
/** Transparent rule-based shopping assistant; it is read-only and uses approved catalog data. */
function aiNormalizeText($value){$value=strtolower(trim((string)$value));$value=preg_replace('/[^a-z0-9\s.-]/',' ',$value);return preg_replace('/\s+/',' ',$value);}
function aiTokens($query){$stop=['a','an','and','are','can','for','i','in','is','it','me','my','need','of','on','please','show','the','to','want','with'];$syn=['phone'=>['charger','cable','wireless'],'mobile'=>['charger','cable','wireless'],'charging'=>['charger','cable','usb-c'],'charge'=>['charger','cable'],'laptop'=>['stand','hub','usb-c'],'computer'=>['mouse','hub','stand'],'audio'=>['earbuds'],'headphone'=>['earbuds'],'headphones'=>['earbuds'],'adapter'=>['hub'],'adaptor'=>['hub']];$tokens=array_values(array_filter(explode(' ',aiNormalizeText($query)),function($t)use($stop){return strlen($t)>1&&!in_array($t,$stop,true)&&!is_numeric($t);}));foreach($tokens as $t)if(isset($syn[$t]))$tokens=array_merge($tokens,$syn[$t]);return array_values(array_unique($tokens));}
function aiPreferences($query){$text=aiNormalizeText($query);$budget=null;if(preg_match('/(?:under|below|less than|within|budget)\s*(?:bdt|tk|taka|rs)?\s*([0-9][0-9,]*)/',$text,$m))$budget=(float)str_replace(',','',$m[1]);elseif(preg_match('/(?:bdt|tk|taka|rs)\s*([0-9][0-9,]*)/',$text,$m))$budget=(float)str_replace(',','',$m[1]);return['budget'=>$budget,'in_stock'=>(bool)preg_match('/\b(in stock|available|available now)\b/',$text)];}
function aiClassifyIntent($query){$text=aiNormalizeText($query);if(preg_match('/\b(order|delivery|track|shipping|shipped|where is)\b/',$text))return'order';if(preg_match('/\b(return|refund|cancel|policy)\b/',$text))return'policy';if(preg_match('/\b(hello|hi|help|support|what can you do)\b/',$text))return'support';return'product_search';}
function aiRankProducts($products,$query){$tokens=aiTokens($query);$pref=aiPreferences($query);$ranked=[];foreach($products as $p){$fields=['name'=>aiNormalizeText($p['name']),'category'=>aiNormalizeText($p['category']),'brand'=>aiNormalizeText($p['brand']),'description'=>aiNormalizeText($p['description']),'specifications'=>aiNormalizeText($p['specifications'])];$score=0;$matches=[];foreach($tokens as $t){if(strpos($fields['name'],$t)!==false){$score+=8;$matches[]=$t;}if(strpos($fields['category'],$t)!==false){$score+=5;$matches[]=$t;}if(strpos($fields['brand'],$t)!==false){$score+=4;$matches[]=$t;}if(strpos($fields['description'],$t)!==false||strpos($fields['specifications'],$t)!==false){$score+=2;$matches[]=$t;}}if(!$score)continue;$p['ai_score']=$score+((int)$p['stock']>0?1:0);$p['ai_matches']=array_values(array_unique($matches));$p['within_budget']=$pref['budget']===null||(float)$p['price']<=$pref['budget'];if(!$p['within_budget'])$p['ai_score']-=3;if($pref['in_stock']&&(int)$p['stock']===0)$p['ai_score']-=4;$ranked[]=$p;}usort($ranked,function($a,$b){return($b['within_budget']<=>$a['within_budget'])?:($b['ai_score']<=>$a['ai_score'])?:((int)$b['stock']<=>(int)$a['stock']);});return array_slice($ranked,0,4);}
function aiBuildResponse($query,$products,$orders=[]){$intent=aiClassifyIntent($query);if($intent==='order'){if(!$orders)return['intent'=>$intent,'confidence'=>'medium','message'=>'Sign in as a buyer to check your orders. You can also open your Buyer Dashboard to track delivery.','products'=>[]];$latest=$orders[0];return['intent'=>$intent,'confidence'=>'high','message'=>'Your latest order (#'.$latest['id'].') is '.$latest['status'].'. You have '.count($orders).' order(s) in total. Open the Buyer Dashboard for the full timeline.','products'=>[]];}if($intent==='policy')return['intent'=>$intent,'confidence'=>'high','message'=>'Returns can be requested for delivered orders from Support. The marketplace team reviews each request and updates its status there.','products'=>[]];if($intent==='support')return['intent'=>$intent,'confidence'=>'high','message'=>'I can find products using natural language, consider a budget, prefer in-stock items, and explain where to track orders or request returns. Try: “wireless mouse under 1000”.','products'=>[]];$ranked=aiRankProducts($products,$query);if(!$ranked||$ranked[0]['ai_score']<4)return['intent'=>'fallback_search','confidence'=>'low','message'=>'I could not confidently match that request. I switched you to standard catalog search, where you can refine the result with filters.','products'=>[],'fallback_query'=>trim($query)];$pref=aiPreferences($query);$available=array_filter($ranked,function($p){return(int)$p['stock']>0;});$within=array_filter($ranked,function($p){return$p['within_budget'];});$message='Here are the strongest approved catalog matches';if($pref['budget']!==null)$message.=' within or closest to your '.$pref['budget'].' BDT budget';if($pref['in_stock'])$message.=', prioritizing available items';$message.='.';if(!$available)$message.=' The closest matches are currently out of stock.';elseif($pref['budget']!==null&&!$within)$message.=' No close match is within that budget, so the nearest options are shown.';return['intent'=>'product_search','confidence'=>$ranked[0]['ai_score']>=10?'high':'medium','message'=>$message,'products'=>$ranked];}
